mapper.sql:
WHERE e.status = 1
AND UPPER(TRIM(e.region_code)) IN #{cv}
AND e.region_code IN #{wr}
AND 1=0
AND e.region_code IN #{rc}
AND ( e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.display_name LIKE CONCAT('%', #{keyword}, '%') OR e.match_name LIKE CONCAT('%', #{keyword}, '%') OR e.agency_key LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT id, emp_no, region_code, agency_key, match_name, display_name, status,
       first_created_at, last_attendance_date, last_seen_at, created_at, updated_at
FROM employees e
WHERE e.region_code = #{regionCode}
  AND e.agency_key = #{agencyKey}
  AND e.match_name = #{matchName}
LIMIT 1

