mapper.update:
UPDATE employee_serial_counters
SET next_seq = LAST_INSERT_ID(next_seq + 1)
WHERE region_code = #{regionCode}

mapper.select:
SELECT tr.employee_id AS employeeId, e.emp_no AS empNo, e.display_name AS displayName, e.region_code AS regionCode, e.agency_key AS agencyKey, tr.work_date AS workDate, tr.arrival AS arrival, tr.departure AS departure, tr.pause_minutes AS pauseMinutes, tr.smart_mark AS smartMark, tr.deleted AS deleted FROM task_records tr INNER JOIN employees e ON tr.employee_id = e.id WHERE tr.deleted = 0 AND tr.task_status = 'confirmed' AND tr.employee_id IS NOT NULL AND tr.work_date >= #{startDate} AND tr.work_date <= #{endDate}
AND e.region_code IN #{rc}
AND ( e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.display_name LIKE CONCAT('%', #{keyword}, '%') OR e.match_name LIKE CONCAT('%', #{keyword}, '%') OR e.agency_key LIKE CONCAT('%', #{keyword}, '%') )
AND UPPER(TRIM(e.region_code)) IN #{cv}
AND e.region_code IN #{wr}
AND 1=0
ORDER BY e.emp_no, tr.work_date
